//! Integration tests for serving the dashboard under a base path
//! (`WEB_BASE_PATH` / `web::mount`) and for the default root behavior.
//!
//! Every redirect, form action, link and cookie path generated by the app
//! must carry the base prefix — the suite walks the real routers (web + API
//! merged, mounted at `/agent`) and checks each Location and Set-Cookie.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use axum::body::Body;
use axum::http::{Request, StatusCode};
use http_body_util::BodyExt;
use telegram_agent::{api, config::Config, db::Db, web, web::WebState};
use tower::ServiceExt;

const BASE: &str = "/agent";

async fn make_state(base: &str) -> (WebState, tempfile::TempDir) {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let db = Db::new(db_path.to_str().unwrap()).unwrap();
    db.create_web_account("owner", "secret", "owner", None)
        .await
        .unwrap();
    db.set_config("setup_done", "1");
    let cfg = Config {
        bot_token: "0:dummy".to_string(),
        owner_id: 1,
        db_path: db_path.to_str().unwrap().to_string(),
        default_channel: None,
        crypto_token: None,
        ai_enabled: false,
        ai_provider: "openai".to_string(),
        ai_base_url: "https://api.openai.com/v1".to_string(),
        ai_api_key: None,
        ai_model: "gpt-4o-mini".to_string(),
        ai_daily_token_budget: None,
        mcp_owner_token: None,
    };
    let state = WebState {
        db: Arc::new(db),
        cfg,
        bot: teloxide::Bot::new("0:dummy"),
        login_attempts: Arc::new(Mutex::new(HashMap::new())),
        base_path: base.to_string(),
    };
    (state, dir)
}

fn app_at(base: &str, state: WebState) -> axum::Router {
    web::mount(base, web::router(state.clone()).merge(api::router(state)))
}

async fn body_string(resp: axum::http::Response<Body>) -> String {
    let bytes = resp.into_body().collect().await.unwrap().to_bytes();
    String::from_utf8_lossy(&bytes).to_string()
}

fn location(resp: &axum::http::Response<Body>) -> String {
    resp.headers()
        .get("location")
        .unwrap()
        .to_str()
        .unwrap()
        .to_string()
}

fn set_cookie(resp: &axum::http::Response<Body>) -> String {
    resp.headers()
        .get("set-cookie")
        .unwrap()
        .to_str()
        .unwrap()
        .to_string()
}

/// The `session=<token>` pair from a Set-Cookie header value.
fn session_pair(set_cookie: &str) -> String {
    set_cookie.split(';').next().unwrap().to_string()
}

/// Every Location observed across this suite must stay under the base path.
fn assert_prefixed(loc: &str) {
    assert!(
        loc.starts_with(BASE),
        "redirect escaped the base path: {loc:?}"
    );
}

#[tokio::test]
async fn login_page_urls_carry_base() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);
    let resp = app
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/login"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);
    let body = body_string(resp).await;
    assert!(
        body.contains(&format!("action=\"{BASE}/login\"")),
        "login form action missing base prefix:\n{body}"
    );
    // The login page is the bare front-door shell (no nav pre-auth); the
    // base-prefixed URL contract now rides on the stylesheet link.
    assert!(
        body.contains(&format!("href=\"{BASE}/assets/app.css\"")),
        "stylesheet link missing base prefix:\n{body}"
    );
}

#[tokio::test]
async fn index_without_session_redirects_to_base_login() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);
    // Trailing-slash base root normalizes to the base, which then lands on
    // the login redirect: /agent/ -> /agent -> /agent/login.
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, BASE);

    let resp = app
        .oneshot(Request::builder().uri(BASE).body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, format!("{BASE}/login"));
}

#[tokio::test]
async fn login_sets_scoped_cookie_and_dashboard_works() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);

    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{BASE}/login"))
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from("username=owner&password=secret"))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, format!("{BASE}/dashboard"));
    let cookie = set_cookie(&resp);
    assert!(cookie.contains("session="), "{cookie}");
    assert!(
        cookie.contains(&format!("Path={BASE}")),
        "cookie path not scoped to base: {cookie}"
    );

    // With the session cookie the dashboard renders; without it redirects.
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/dashboard"))
                .header("cookie", session_pair(&cookie))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);

    let resp = app
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/dashboard"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, format!("{BASE}/login"));
}

#[tokio::test]
async fn invalid_plan_redirects_to_base_plans() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{BASE}/login"))
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from("username=owner&password=secret"))
                .unwrap(),
        )
        .await
        .unwrap();
    let cookie = session_pair(&set_cookie(&resp));

    let resp = app
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{BASE}/plan"))
                .header("content-type", "application/x-www-form-urlencoded")
                .header("cookie", cookie)
                .body(Body::from(
                    "name=bronze&price=10&asset=TON&duration_days=notanumber",
                ))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, format!("{BASE}/plans"));
}

#[tokio::test]
async fn logout_clears_scoped_cookie() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);
    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{BASE}/login"))
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from("username=owner&password=secret"))
                .unwrap(),
        )
        .await
        .unwrap();
    let cookie = session_pair(&set_cookie(&resp));

    let resp = app
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/logout"))
                .header("cookie", cookie)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    let loc = location(&resp);
    assert_prefixed(&loc);
    assert_eq!(loc, format!("{BASE}/login"));
    let cleared = set_cookie(&resp);
    assert!(cleared.contains("Max-Age=0"), "{cleared}");
    assert!(
        cleared.contains(&format!("Path={BASE}")),
        "clearing cookie path not scoped to base: {cleared}"
    );
}

#[tokio::test]
async fn every_redirect_stays_under_base() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);

    // Logged-out walk over every redirecting GET route. "/" (the base root
    // with trailing slash) first normalizes to the base itself.
    for path in [
        "/",
        "/dashboard",
        "/channels",
        "/plans",
        "/posts",
        "/logout",
    ] {
        let resp = app
            .clone()
            .oneshot(
                Request::builder()
                    .uri(format!("{BASE}{path}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert!(
            resp.status().is_redirection(),
            "{path} should redirect, got {}",
            resp.status()
        );
        let loc = location(&resp);
        assert_prefixed(&loc);
        let expected = if path == "/" {
            BASE.to_string()
        } else {
            format!("{BASE}/login")
        };
        assert_eq!(loc, expected, "{path} -> {loc}");
    }

    // And the login POST redirect.
    let resp = app
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{BASE}/login"))
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from("username=owner&password=secret"))
                .unwrap(),
        )
        .await
        .unwrap();
    assert!(resp.status().is_redirection());
    assert_prefixed(&location(&resp));
}

#[tokio::test]
async fn health_under_base() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);
    let resp = app
        .oneshot(
            Request::builder()
                .uri(format!("{BASE}/health"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);
    let v: serde_json::Value = serde_json::from_str(&body_string(resp).await).unwrap();
    assert_eq!(v["status"], "ok");
}

#[tokio::test]
async fn api_login_under_base() {
    let (state, _dir) = make_state(BASE).await;
    let app = app_at(BASE, state);
    let resp = app
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(format!("{BASE}/api/v1/auth/login"))
                .header("content-type", "application/json")
                .body(Body::from(r#"{"username":"owner","password":"secret"}"#))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);
    let v: serde_json::Value = serde_json::from_str(&body_string(resp).await).unwrap();
    assert!(v["token"].as_str().is_some_and(|t| !t.is_empty()), "{v}");
}

#[tokio::test]
async fn default_mount_at_root() {
    let (state, _dir) = make_state("").await;
    let app = app_at("", state);

    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .uri("/login")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);

    let resp = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/login")
                .header("content-type", "application/x-www-form-urlencoded")
                .body(Body::from("username=owner&password=secret"))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    assert_eq!(location(&resp), "/dashboard");
    let cookie = set_cookie(&resp);
    assert!(
        cookie.contains("Path=/;"),
        "default cookie must be scoped to Path=/;: {cookie}"
    );

    // Index without a session still redirects to /login.
    let resp = app
        .oneshot(Request::builder().uri("/").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::SEE_OTHER);
    assert_eq!(location(&resp), "/login");
}
